"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79442"],{41597(e){e.exports=JSON.parse('{"id":"FIN-526","slug":"beneficiary","term":"Beneficiary","also_known_as":[],"difficulty":"Beginner","definition":"A beneficiary is a person or organisation named to receive money, property or other benefits from an insurance policy, pension, investment account, will or trust.","explanation":["Many financial products allow you to name who should receive the money if you die. Life insurance policies, pensions and retirement accounts usually ask for a beneficiary when they are set up. Wills and trusts also name beneficiaries for the assets they cover.","For example, a person might name their spouse as the main beneficiary of a life insurance policy and their two children as contingent beneficiaries, who would receive the money if the spouse had died first.","Keeping beneficiary designations up to date is important. In many places, the beneficiary named on an account or policy receives the money directly, even if a will says something different. A forgotten designation naming a former partner, for example, could send money to someone the account holder no longer intended to benefit.","Beneficiaries of a trust have rights to receive income or assets according to the trust\'s terms, while the trustee manages the assets on their behalf. Naming a beneficiary can also help money pass more quickly, because it may avoid lengthy legal processes after death."],"note":"","total":1500,"prev":{"slug":"beneficial-owner","term":"Beneficial Owner"},"next":{"slug":"bermudan-option","term":"Bermudan Option"}}')}}]);